#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int data; struct Node *link; } Node;
static size_t count_nodes(const Node *p) {
    size_t count=0;
    while (p != NULL) { ++count; p=p->link; }
    return count;
}
static void clear(Node *head) {
    while (head != NULL) { Node *next=head->link; free(head); head=next; }
}
int main(void) {
    int n, value;
    Node *head=NULL, *tail=NULL;
    printf("노드의 개수 : ");
    if (scanf("%d", &n)!=1 || n<0) return 1;
    for (int i=0; i<n; ++i) {
        printf("노드 #%d 데이터 : ", i+1);
        if (scanf("%d", &value)!=1) { clear(head); return 1; }
        Node *node=malloc(sizeof *node);
        if (node==NULL) { clear(head); return 1; }
        node->data=value; node->link=NULL;
        if (tail==NULL) head=node; else tail->link=node;
        tail=node;
    }
    printf("연결 리스트 노드의 개수 = %zu\n", count_nodes(head));
    clear(head);
    return 0;
}
